"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["80524"],{58201(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.inscricao_sem_edicao_do_enem","status":422,"titulo":"A classifica\xe7\xe3o usa as notas do ENEM, e o formul\xe1rio de inscri\xe7\xe3o n\xe3o pede a edi\xe7\xe3o a todo candidato"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.inscricao_sem_edicao_do_enem","requisitos":[],"oQueAconteceu":["O processo recebe inscri\xe7\xf5es pelo sistema e classifica os candidatos pela nota do\\nEnem, mas o formul\xe1rio de inscri\xe7\xe3o n\xe3o tem o campo `EDICAO_ENEM` em condi\xe7\xf5es\\nde sempre ser respondido. A edi\xe7\xe3o do Enem diz de qual prova vem a nota do\\ncandidato, e sem ela a classifica\xe7\xe3o n\xe3o sabe qual nota buscar.","O campo \xe9 considerado em condi\xe7\xf5es quando todas as condi\xe7\xf5es abaixo valem:","- \xe9 um item avulso, e n\xe3o um item de grupo que se repete;\\n- n\xe3o tem pr\xe9-condi\xe7\xe3o para aparecer;\\n- \xe9 obrigat\xf3rio sempre, e n\xe3o apenas em certos casos;\\n- est\xe1 numa se\xe7\xe3o que n\xe3o tem exibi\xe7\xe3o condicional.","Um campo com `EDICAO_ENEM` que falha em qualquer dessas condi\xe7\xf5es, ou a falta\\ndo campo, produz esta recusa. A confer\xeancia s\xf3 acontece quando o processo j\xe1\\ntem formul\xe1rio de inscri\xe7\xe3o."],"comoResolver":["No formul\xe1rio de inscri\xe7\xe3o do processo, deixe o item `EDICAO_ENEM` como item\\navulso, sem pr\xe9-condi\xe7\xe3o, com obrigatoriedade \\"sempre\\", dentro de uma se\xe7\xe3o que\\nsempre aparece. Se o campo j\xe1 existe, ajuste o que for apontado acima; se n\xe3o\\nexiste, inclua-o.","Em processo j\xe1 publicado, a altera\xe7\xe3o do formul\xe1rio \xe9 feita numa retifica\xe7\xe3o.\\nDepois, repita a opera\xe7\xe3o recusada."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);